                style: { paddingTop: '5px' },
                children: [
                  metric('费用', '{{get inputData "todayCost" default="$0.00"}}', 'start'),
                  metric('会话', '{{get inputData "todaySessions" default="0"}}', 'center'),
                  metric('活跃', '{{get inputData "todayActive" default="0秒"}}', 'end'),
                ],
              },
            },
            {
              type: 'div',
              props: {
                tw: 'flex flex-row shrink-0 items-center min-w-0 gap-[6px] text-10-chillduansans',
                children: [
                  {
                    type: 'span',
                    props: {
                      tw: 'font-bold shrink-0 text-10-chillduansans',
                      children: '主力',
